  function focusRating(){(rating.current?.querySelector<HTMLElement>('[role=radio][aria-checked=true]')??rating.current?.querySelector<HTMLElement>('[role=radio]'))?.focus();}
  function outcome(result:'complete'|'fail'|'cancel'){
