for(let index=0;index<frames;index++){const t=index/rate;const envelope=Math.min(1,t/.03,(seconds-t)/.03);bytes.writeInt16LE(Math.round(32767*.08*envelope*Math.sin(2*Math.PI*frequency*t)),44+index*2);}
