.composition-settings { display:flex; flex-wrap:wrap; align-items:end; gap:16px; }
.composition-settings label { display:flex; flex-direction:column; gap:8px; max-inline-size:100%; }
.composition-settings input[type=range], .composition-settings select { min-block-size:44px; }
.composition-settings .composition-direction { flex-direction:row; align-items:center; min-block-size:44px; }
.composition-container { container-type:inline-size; inline-size:100%; min-inline-size:0; }
.composition-shell { display:grid; gap:16px; min-inline-size:0; }
.composition-shell > [hidden] { display:none; }
.composition-list, .composition-task, .composition-context { min-inline-size:0; padding:16px; border:1px solid var(--color-muted-foreground); border-radius:var(--radius-md); }
.composition-shell p, .composition-shell h3, .composition-shell h4, .composition-shell label { overflow-wrap:anywhere; }
.composition-list ul { display:grid; gap:16px; list-style:none; margin:16px 0 0; padding:0; }
.composition-list li, .composition-task, .composition-context { display:flex; flex-direction:column; gap:12px; }
.composition-task label { display:flex; flex-direction:column; gap:8px; }
.composition-task textarea { inline-size:100%; min-block-size:120px; }
.composition-actions { display:flex; flex-wrap:wrap; gap:12px; }
.composition-shell .mt-btn { min-block-size:44px; block-size:auto; max-inline-size:100%; white-space:normal; overflow-wrap:anywhere; }
.composition-task h3 { scroll-margin-block-start:96px; }
.composition-container[data-mode=feed] .composition-list li { padding-block-end:16px; border-block-end:1px solid var(--color-muted-foreground); }
@container (min-width:640px) {
  .composition-container[data-mode=list-detail] .composition-shell { grid-template-columns:minmax(0,var(--composition-leading)) minmax(0,var(--composition-trailing)); }
  .composition-container[data-mode=feed] .composition-list ul { grid-template-columns:repeat(2,minmax(0,1fr)); }
}
@container (min-width:900px) {
  .composition-container[data-mode=supporting] .composition-shell { grid-template-columns:minmax(0,var(--composition-leading)) minmax(0,var(--composition-trailing)); }
  .composition-container[data-mode=feed] .composition-list ul { grid-template-columns:repeat(3,minmax(0,1fr)); }
}
@media (forced-colors:active) {
  .composition-list, .composition-task, .composition-context, .composition-list li { border-color:CanvasText; }
}

